package net.civeira.phylax.feature.observe.observedalertrule.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRule;
import net.civeira.phylax.feature.observe.observedalertrule.domain.valueobject.WindowMinutesVO;

class WindowMinutesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of window minutes of observed alert rule")
  void test_window_minutes_value_holder_assign_plain_value() {
    Object holder = new Object();
    WindowMinutesValueHolder<Object> value = new WindowMinutesValueHolder<>(holder);
    Assertions.assertSame(holder, value.windowMinutes(1), "Setters must return the holder");
    Assertions.assertTrue(value.getWindowMinutesValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getWindowMinutes().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of window minutes of observed alert rule")
  void test_window_minutes_value_holder_assign_value_object() {
    Object holder = new Object();
    WindowMinutesValueHolder<Object> value = new WindowMinutesValueHolder<>(holder);
    WindowMinutesVO vo = WindowMinutesVO.from(1);
    Assertions.assertFalse(value.getWindowMinutesValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.windowMinutes(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getWindowMinutesValue().orElseThrow());
    Assertions.assertSame(holder, value.windowMinutes(Optional.empty()));
    Assertions.assertFalse(value.getWindowMinutesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.windowMinutes(Optional.of(vo)));
    Assertions.assertSame(vo, value.getWindowMinutesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of window minutes of observed alert rule against the original")
  void test_window_minutes_value_holder_read() {
    Object holder = new Object();
    WindowMinutesValueHolder<Object> value = new WindowMinutesValueHolder<>(holder);
    WindowMinutesVO vo = WindowMinutesVO.from(1);
    WindowMinutesVO other = WindowMinutesVO.from(1);
    ObservedAlertRule original = Mockito.mock(ObservedAlertRule.class);
    Mockito.when(original.getWindowMinutesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readWindowMinutes(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readWindowMinutes(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.windowMinutes(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readWindowMinutes(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readWindowMinutes(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of window minutes of observed alert rule")
  void test_window_minutes_value_holder_unset() {
    Object holder = new Object();
    WindowMinutesValueHolder<Object> value = new WindowMinutesValueHolder<>(holder);
    WindowMinutesVO vo = WindowMinutesVO.from(1);
    value.windowMinutes(vo);
    Assertions.assertSame(holder, value.unsetWindowMinutesIfMatches("windowMinutes_other"));
    Assertions.assertTrue(value.getWindowMinutesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetWindowMinutesIfMatches("windowMinutes"));
    Assertions.assertFalse(value.getWindowMinutesValue().isPresent(),
        "The field name must clear the value");
    value.windowMinutes(vo);
    Assertions.assertSame(holder, value.unsetWindowMinutes());
    Assertions.assertFalse(value.getWindowMinutesValue().isPresent(), "Unset must clear the value");
  }
}
